    const [_, firstWord, secondWord] = match;
    // If the previous word was an article (determiner), add the second word before the first one
    if (previousAdjectiveWasArticle) {
      newWords.push(secondWord);
      newWords.push(firstWord);
      previousAdjectiveWasArticle = false;
