     let mut num = n as u32; // Convert n to unsigned integer for bitwise operations
     num &= !1; // Perform bitwise AND with inverted 1 (1's complement), which sets the least significant bit to 0 if even
     num > 0 as u32 // Check if the number is zero, which indicates an even number
