```javascript
import { createContext, useState } from "react";

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [message, setMessage] = useState(null);

  return (
    <ToastContext.Provider value={{ message, setMessage }}>
      {children}
    </ToastContext.Provider>
  );
};
```

This creates a custom context called `ToastContext`, which includes a `ToastProvider` component that sets up state for storing the toast message and a function to update it.

