import React, { useState } from 'react';
import { useCombobox } from 'downshift';

interface Option {
  value: string;
  label: string;
}

async function searchEmails(prefix: string): Promise<Option[]> {
  // Call your API or perform local search here
  const response = await fetch('/api/search-emails?prefix=' + prefix);
  const data = await response.json();
  return data.map((email: any) => ({ value: email, label: email }));
}

const EmailInput = () => {
  const [inputItems, setInputItems] = useState<Option[]>([]);
  const { isOpen, getMenuProps, getComboboxProps, highlightedIndex, getItemProps, getLabelProps } = useCombobox({
    items: inputItems,
    onInputValueChange: async ({ inputValue }) => {
      const newItems = await searchEmails(inputValue);
      setInputItems(newItems);
    },
  });

  return (
    <div>
      <label {...getLabelProps()}>Email address</label>
      <input {...getComboboxProps()} />
      <ul {...getMenuProps()}>
        {isOpen &&
          inputItems.map((item, index) => (
            <li key={item.value} {...getItemProps({ item, index })} style={{ backgroundColor: highlightedIndex === index ? '#f5f5f5' : '' }}>
              {item.label}
            </li>
          ))}
      </ul>
    </div>
  );
};

export default EmailInput;
```

