 To identify if a given sentence in Go contains a double negative, you can follow these steps:

1. Create a slice of specific negative words.
2. Split the given sentence into words.
3. Iterate through each word in the sentence.
4. Check if the current word is in the slice of negative words or if the word before it is "not" and the next word is a negative word.
5. If a double negative is found, print a message indicating that.

Here's an example Go code snippet to accomplish this task:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"ain't", "isn't", "aren't", "hasn't", "haven't", "hadn't", "doesn't", "don't", "didn't", "won't", "wouldn't", "shall not", "shouldn't", "can't", "couldn't", "might not", "mustn't", "dare not", "needn't"}
	sentence := "He isn't not worried about the coronavirus situation"

	words := strings.Split(sentence, " ")
	for i := 0; i < len(words)-2; i++ { // iterate through each word except the last two
		currentWord := words[i]
		nextTwoWords := words[i+1:] // slice of next two words
		if containsNegativeWord(currentWord, negativeWords) && containsDoubleNegation(nextTwoWords) {
			fmt.Println("Double Negative Detected!")
			return
		}
	}

	fmt.Println("No Double Negative Found.")
}

// checks if a given word is in the slice of negative words
func containsNegativeWord(word string, negativeWords []string) bool {
	for _, negWord := range negativeWords {
		if strings.EqualFold(word, negWord) {
			return true
		}
	}
	return false
}

